import type { NestedConstsValue } from './stylex-nested-utils';
import type { Unflattened } from './stylex-nested-utils';
declare function styleXDefineConstsNested(
  nestedConstants: { readonly [$$Key$$: string]: NestedConstsValue },
  options: Readonly<
    Omit<Partial<StyleXOptions>, keyof { exportId: string }> & {
      exportId: string;
    }
  >,
): [
  { [$$Key$$: string]: Unflattened<string | number> },
  { [$$Key$$: string]: InjectableConstStyle },
];
export default styleXDefineConstsNested;
